/* controls ---------------------------------------------------------------- */
/* controlReset() also hides .mf-section-break/.mf-section-title, which is what stops step_1 - whose
   pageBreak is false - painting a visible "Client" heading the mock has no room for. */

/* megaform sets font-family on label/input/select/textarea with !important, so an authored
   <span> inside a <label> inherits the HOST typeface no matter what the shell root declares.
   Element selectors are (0,3,1) here - above megaform, below every authored class rule - and
   <i> is left alone so Font Awesome keeps its own family. */
.mfp.mfp-icx.mfp-native-generated label,.mfp.mfp-icx.mfp-native-generated span,.mfp.mfp-icx.mfp-native-generated p,.mfp.mfp-icx.mfp-native-generated div,.mfp.mfp-icx.mfp-native-generated ul,.mfp.mfp-icx.mfp-native-generated li,.mfp.mfp-icx.mfp-native-generated h1,.mfp.mfp-icx.mfp-native-generated h2,.mfp.mfp-icx.mfp-native-generated h3,.mfp.mfp-icx.mfp-native-generated button{font-family:inherit!important}
