.mfp.mfp-icx.mfp-native-generated .mf-option-group--cards .mf-option-copy{display:block;width:100%}

/* the underline field, exactly the mock's inp string */
.mfp.mfp-icx.mfp-native-generated .mf-input[class],.mfp.mfp-icx.mfp-native-generated .mf-select[class]{width:100%!important;box-sizing:border-box!important;
